import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused bias addition and summation kernel
fused_bias_sum_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void fused_bias_sum_kernel(
    const scalar_t* input,
    const scalar_t* bias,
    scalar_t* output,
    int B,
    int C
) {
    extern __shared__ __align__(sizeof(scalar_t)) unsigned char shared_mem[];
    scalar_t* sdata = reinterpret_cast<scalar_t*>(shared_mem);

    int b = blockIdx.x;
    if (b >= B) return;

    const scalar_t* input_ptr = input + b * C;
    const scalar_t* bias_ptr = bias;

    scalar_t sum = 0;

    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        sum += input_ptr[c] + bias_ptr[c];
    }

    sdata[threadIdx.x] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[b] = sdata[0];
    }
}

torch::Tensor fused_bias_sum_cuda(torch::Tensor input, torch::Tensor bias) {
    TORCH_CHECK(input.device().is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(bias.device().is_cuda(), "Bias must be a CUDA tensor");
    TORCH_CHECK(input.size(2) == 1 && input.size(3) == 1 && input.size(4) == 1,
                "Input must have spatial dimensions 1x1x1 after global average pooling");
    TORCH_CHECK(bias.size(0) == input.size(1), "Bias size must match input channels");
    TORCH_CHECK(bias.size(1) == 1 && bias.size(2) == 1 && bias.size(3) == 1,
                "Bias must have shape (C, 1, 1, 1)");

    int B = input.size(0);
    int C = input.size(1);
    auto output = torch::zeros({B, 1, 1, 1, 1}, input.options());
    int threads = 256;
    int blocks = B;

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "fused_bias_sum_cuda", ([&] {
        fused_bias_sum_kernel<scalar_t><<<blocks, threads, threads * sizeof(scalar_t)>>>(
            input.contiguous().data_ptr<scalar_t>(),
            bias.contiguous().data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            B,
            C
        );
    }));

    return output;
}
"""

fused_bias_sum_cpp_source = "torch::Tensor fused_bias_sum_cuda(torch::Tensor input, torch::Tensor bias);"

fused_bias_sum = load_inline(
    name='fused_bias_sum',
    cpp_sources=fused_bias_sum_cpp_source,
    cuda_sources=fused_bias_sum_source,
    functions=['fused_bias_sum_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, divisor, pool_size, bias_shape, sum_dim):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.conv.weight.data.div_(divisor)
        self.conv.bias.data.div_(divisor)
        self.max_pool = nn.MaxPool3d(pool_size)
        self.global_avg_pool = nn.AdaptiveAvgPool3d((1, 1, 1))
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.sum_dim = sum_dim
        self.fused_bias_sum = fused_bias_sum

    def forward(self, x):
        x = self.conv(x)
        x = self.max_pool(x)
        x = self.global_avg_pool(x)
        x = self.fused_bias_sum.fused_bias_sum_cuda(x, self.bias)
        return x
